node -e "
const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
const text = data.toString('utf8');
// Look for date references near the email
const idx = text.indexOf('High Priority: Onboarding Equipment Setup Needed - Follow-Up');
if (idx >= 0) {
  const start = Math.max(0, idx - 2000);
  const end = Math.min(text.length, idx + 3000);
  // look for any date patterns
  const chunk = text.substring(start, end);
  const dates = chunk.match(/20\d{2}[-\/]\d{2}[-\/]\d{2}|20\d{6}/g);
  console.log('Dates found:', dates);
}
"

